def P(de, pasos, items, clips=None, **k):
    # la tienda es un fondo muy claro y con detalle: mas oscuro para que se lean los rotulos
    if clips == [K] and "luz" not in k:
        k["luz"] = 0.5
    G.plano(de, pasos, items, clips=clips, **k)


